SELECT sbr.id, sbr.code, sbr.platform_return_no as platformReturnNo, sbr.platform_order_no as platformOrderNo, sbr.so_id as soId, sbr.so_code as soCode, sbr.dict_platform as platform, sbr.shop_id as shopId, sbr.amount as orderAmount, sbr.currency, concat(sbr.amount ,sbr.currency) as completeOrderAmount, sbr.type, sbr.reason, sbr.status, sbrd.id as detailId, sbrd.sku_id as skuId, sbrd.sku_no as skuNo, sbrd.platform_sku_no as platformSkuNo, sbrd.sale_qty as saleQty, sbrd.return_qty as returnQty, sbrd.remark, sbr.create_time as sysCreateTime, sbr.sys_return_time as sysReturnTime from so_b2c_return sbr inner join so_b2c_return_detail sbrd on sbr.id = sbrd.main_id and sbrd.is_deleted = false where ${params.sqlMap.default} and sbr.is_deleted =FALSE
${params.permissionSql}
order by sbr.create_time

SELECT sbr.id, sbr.code, sbr.so_id as soId, sbr.status, sbr.dict_platform as platform, sbr.shop_id as shopId, sbrd.id as detailId, sbrd.sku_id as skuId, sbrd.sku_no as skuNo, sbrd.sale_qty as saleQty, sbrd.return_qty as returnQty from so_b2c_return sbr inner join so_b2c_return_detail sbrd on sbr.id = sbrd.main_id and sbrd.is_deleted = false where sbr.id in
#{id}
and sbr.is_deleted =FALSE order by sbr.create_time
